pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _testBurn(uint256 v) internal {
        vm.assume(msg.sender == c.owner());
        vm.assume(v != 1);
        uint256 before;
        try c.totalSupply() returns (uint256 __r) { before = __r; } catch { return; }
        try c.burn(v) {} catch { return; }
        assertTrue(c.totalSupply() == before - v);
    }

    function testFuzz_testBurn(uint256 v) public {
        _testBurn(v);
    }

    receive() external payable {}
}
